#!/usr/bin/env python3
"""Regenerate storyboard.md from script/timing.json (run after build_voice.py / align_voice.py)."""
import json, os
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
T = json.load(open(f"{ROOT}/script/timing.json"))
def mmss(x): return f"{int(x//60):02d}:{x%60:05.2f}"
META = {
"scene1": ("«Хук»", "Тёмный экран → цифровые часы прокручивают 2025→2045 → город «просыпается»: здания вырастают слоями, окна загораются одно за другим. На крыше — силуэт человека. Камера медленно наезжает, параллакс трёх слоёв.", "2045. БУДУЩЕЕ УЖЕ БЛИЖЕ, ЧЕМ КАЖЕТСЯ.", "тиканье часов, удар на «2045», россыпь «пингов» окон, свуш заголовка", "медленно, низко, с загадкой"),
"scene2": ("«Умный дом»", "Разрез квартиры: умное стекло очищается, створки разъезжаются, восходит солнце. Лампы включаются по очереди. ИИ-орб, голографические панели (погода, план дня, климат). Робо-манипулятор готовит кофе, пар, робот-пылесос, счётчик «0 прикосновений».", "ТВОЙ ДОМ ПОНИМАЕТ ТЕБЯ.", "сервоприводы створок, щелчки света, UI-блипы, налив кофе, колокольчик «КОФЕ ГОТОВ»", "тепло, уверенно"),
"scene3": ("«Транспорт»", "Боковой трекинг: беспилотное авто едет по умному городу без пробок, светофоры обмениваются данными с машиной (V2X-волны и пакеты). Резкий перелёт в салон: пустое водительское место, руль вращается сам, маршрут рисуется на лобовом AR-экране, таймер прибытия.", "ТРАНСПОРТ БЕЗ ВОДИТЕЛЯ.", "гул электромотора, пролёты, V2X-чирпы, свуш-переход в салон, сигнал прибытия", "уверенно, поступательно"),
"scene4": ("«Роботы и работа»", "Цех: гуманоидные роботы носят ящики, два манипулятора на портале собирают кузова на конвейере (искры сварки), опасная зона с печью. Инженер в каске у голографической панели управления линией.", "РОБОТЫ МЕНЯЮТ РАБОТУ.", "серво-движения, треск сварки, шаги роботов, гул конвейера", "уверенно, объясняюще"),
"scene5": ("«Медицина»", "Лаборатория: голографическая модель тела со сканирующим кольцом, ИИ-анализ рентгена с рамкой обнаружения, ЭКГ, варианты лечения. Роботы-хирурги опускаются к пациенту, врач ставит финальное решение «ЗА ВРАЧОМ ✓».", "МЕДИЦИНА НОВОГО ПОКОЛЕНИЯ.", "писк ЭКГ, скан-свипы, серво хирургов, подтверждающий колокольчик", "серьёзно, уверенно"),
"scene6": ("«Образование»", "Ученик в AR-очках за партой. Стены класса рассыпаются, открывается космос; голограмма-учитель объясняет Солнечную систему (орбиты, планеты). Панели персонального темпа и VR-лаборатории.", "ЗНАНИЯ БЕЗ ГРАНИЦ.", "грохот стен, «рождение» системы, мерцание голограммы, UI-блипы", "живо, с интересом"),
"scene7": ("«Энергия»", "Солнечные панели с бликом, ветряки, накопители заряда, город и башня центра управления. Энергетические линии соединяют всё в одну сеть; на панели кривые генерации и потребления сходятся в «БАЛАНС 100%».", "ЭНЕРГИЯ БУДУЩЕГО.", "ветер, электрические разряды линий, нарастающий гул сети, финальный колокольчик", "уверенно, с подъёмом"),
"scene8": ("«Обратная сторона»", "Город гаснет, палитра уходит в красный. Силуэт человека в потоках данных, голографическое лицо сканирует его. Предупреждения: приватность, кибератака, зависимость от ИИ 87%. Глитч-сбой «СИСТЕМА НЕ ОТВЕЧАЕТ».", "ЦЕНА ТЕХНОЛОГИЧЕСКОГО ПРОГРЕССА.", "тревожный дрон, сердцебиение, красные сигналы, глитч-удар", "медленнее, серьёзно, с напряжением"),
"scene9": ("«Финал-клиффхэнгер»", "Человек в центре города, вокруг — десятки голограмм. Внезапно все исчезают (тишина, сердцебиение). Камера едет в голову → глаз; в отражении зрачка — цифровой интерфейс «2045». Чёрный экран, финальный титр.", "БУДУЩЕЕ СОЗДАЁМ МЫ. / Ты готов к 2045 году?", "power-down, пульс, нарастающее напряжение, удар на глазе, шиммер, финальный удар", "очень медленно и весомо; сильный акцент на финальном вопросе"),
}
L = ["# Storyboard — «2045: МИР, КОТОРЫЙ ДУМАЕТ ЗА ТЕБЯ»\n",
     f"Формат 9:16 · 1080×1920 · 30 fps · русский язык · длительность {T['duration']:.1f} c · 9 сцен-компонентов.\n",
     "Тайминги сцен и субтитров рассчитаны по реальной озвучке (пословное выравнивание распознавателем речи).\n",
     "| # | Время | Сцена | Длит. |\n|---|---|---|---|"]
for i, s in enumerate(T["scenes"]):
    L.append(f"| {i+1} | {mmss(s['start'])} – {mmss(s['end'])} | {META[s['id']][0]} | {s['duration']:.2f} c |")
L.append("")
for i, s in enumerate(T["scenes"]):
    m = META[s["id"]]
    L += [f"## Сцена {i+1} — {m[0]} ({mmss(s['start'])} – {mmss(s['end'])})\n", f"**Визуал.** {m[1]}\n", f"**Экранный текст.** «{m[2]}»\n",
          "**Закадровый текст.** " + " ".join(c["text"].replace("*", "") for c in T["chunks"] if c["scene"] == s["id"]) + "\n",
          f"**Подача диктора.** {m[4]}\n", f"**Звук.** {m[3]}\n", "**Реплики (синхро):**\n"]
    L += [f"- `{mmss(c['start'])}`–`{mmss(c['end'])}` {c['text'].replace('*', '')}" for c in T["chunks"] if c["scene"] == s["id"]]
    L.append("")
L.append("## Единый визуальный стиль\n\n- Палитра: ночной синий `#01040b → #08213f`, акценты cyan `#22e4ff`, blue `#2f7bff`; сцена 8 — тревожный красный `#ff4d6a`.\n- Типографика: Montserrat 800 (заголовки), Inter 700 (субтитры), JetBrains Mono (HUD).\n- Приёмы: параллакс слоёв, медленные push-in камеры, голографические панели со scanlines, свечение, частицы-пыль, вспышка-переход со световым лучом между сценами.\n")
open(f"{ROOT}/storyboard.md", "w").write("\n".join(L))
print("storyboard.md written")
